/**
 * Adjustments on a job's charges (punch list #254, PR 3): what the office changes on top of the record, in the Charges
 * window — a day's crew shape, a day left off, a material line passed through at cost or left off — each with a
 * reason and who made it, kept on the job (`job_charge_adjustments`) and never on a clock session or an invoice. The
 * Job Summary row, the Charges window and every statement made after read them. Pure: the reads hand in rows, the
 * kernels hand back the crew-day inputs and material lines with the adjustments applied, and the words for the log.
 */
import type { CrewShape } from './rateCard.ts'
import { CREW_SHAPE_LOWER, parseCrewShape } from './rateCard.ts'
import type { MaterialLineInput } from '../../../../../../src/lib/charges/materialsCharged.ts'

export type ChargeAdjustmentKind = 'day_shape' | 'day_off' | 'line_pass_through' | 'line_off'

export const CHARGE_ADJUSTMENT_KINDS: readonly ChargeAdjustmentKind[] = ['day_shape', 'day_off', 'line_pass_through', 'line_off']

export type ChargeAdjustment = {
  id: string
  jobId: string
  kind: ChargeAdjustmentKind
  /** YYYY-MM-DD for a day adjustment; the material line's id for a line adjustment. */
  target: string
  /** The shape a day is set to, for `day_shape`. */
  shape: CrewShape | null
  /** A line adjustment's cost as it stood when made; null on a day adjustment. */
  amount: number | null
  reason: string
  madeByName: string | null
  madeAt: string
}

/** A row of `job_charge_adjustments` as the read hands it over; anything unreadable is dropped. */
export function chargeAdjustmentFromRow(raw: unknown): ChargeAdjustment | null {
  if (!raw || typeof raw !== 'object') return null
  const r = raw as Record<string, unknown>
  const kind = typeof r.kind === 'string' && (CHARGE_ADJUSTMENT_KINDS as readonly string[]).includes(r.kind) ? (r.kind as ChargeAdjustmentKind) : null
  const id = typeof r.id === 'string' ? r.id : null
  const jobId = typeof r.job_id === 'string' ? r.job_id : null
  const target = typeof r.target === 'string' ? r.target : null
  if (!kind || !id || !jobId || !target) return null
  const shape = kind === 'day_shape' ? parseCrewShape(r.shape) : null
  if (kind === 'day_shape' && !shape) return null
  const madeBy = r.made_by_user as { name?: unknown } | null | undefined
  const amountNum = typeof r.amount === 'number' ? r.amount : typeof r.amount === 'string' ? Number(r.amount) : NaN
  return {
    id,
    jobId,
    kind,
    target,
    shape,
    amount: Number.isFinite(amountNum) && amountNum >= 0 ? amountNum : null,
    reason: typeof r.reason === 'string' ? r.reason : '',
    madeByName: madeBy && typeof madeBy.name === 'string' ? madeBy.name : typeof r.made_by_name === 'string' ? r.made_by_name : null,
    madeAt: typeof r.created_at === 'string' ? r.created_at : '',
  }
}

/** The day adjustments by date, the newest of a kind winning; the line adjustments by line id. */
export type AppliedAdjustments = {
  dayShape: Map<string, ChargeShapeOverride>
  dayOff: Set<string>
  linePassThrough: Set<string>
  lineOff: Set<string>
}

export type ChargeShapeOverride = { shape: CrewShape; reason: string; madeByName: string | null }

export function indexAdjustments(rows: ReadonlyArray<ChargeAdjustment>): AppliedAdjustments {
  const out: AppliedAdjustments = { dayShape: new Map(), dayOff: new Set(), linePassThrough: new Set(), lineOff: new Set() }
  const sorted = [...rows].sort((a, b) => (a.madeAt < b.madeAt ? -1 : a.madeAt > b.madeAt ? 1 : 0))
  for (const a of sorted) {
    if (a.kind === 'day_shape' && a.shape) out.dayShape.set(a.target, { shape: a.shape, reason: a.reason, madeByName: a.madeByName })
    else if (a.kind === 'day_off') out.dayOff.add(a.target)
    else if (a.kind === 'line_pass_through') out.linePassThrough.add(a.target)
    else if (a.kind === 'line_off') out.lineOff.add(a.target)
  }
  return out
}

/** The material lines with the line adjustments applied. */
export function adjustMaterialLines<T extends MaterialLineInput>(lines: ReadonlyArray<T>, applied: AppliedAdjustments): T[] {
  return lines.map((l) => ({ ...l, passThrough: l.passThrough || applied.linePassThrough.has(l.id), leftOff: l.leftOff || applied.lineOff.has(l.id) }))
}

/** One line of the adjustments log, and the office copy: `Sat Apr 25 · set to a tech alone · Zed was alone · Dana`. */
export function chargeAdjustmentWords(a: ChargeAdjustment, dayWords: (ymd: string) => string, lineLabel: (id: string) => string): string {
  const what =
    a.kind === 'day_shape' && a.shape
      ? `${dayWords(a.target)} · set to ${CREW_SHAPE_LOWER[a.shape]}`
      : a.kind === 'day_off'
        ? `${dayWords(a.target)} · left off`
        : a.kind === 'line_pass_through'
          ? `${lineLabel(a.target)} · passed through at cost`
          : `${lineLabel(a.target)} · left off`
  const tail = [a.reason.trim(), a.madeByName ?? ''].filter(Boolean).join(' · ')
  return tail ? `${what} · ${tail}` : what
}

/** The words the window's save press carries: `Save 1 adjustment`, `Save 3 adjustments`; dead with none. */
export function saveAdjustmentsLabel(n: number): string {
  return n === 1 ? 'Save 1 adjustment' : `Save ${n} adjustments`
}
